import sys

def min_possible_value(N, K):
    return min(N % K, (K - N) % K)

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    K = int(data[1])
    result = min_possible_value(N, K)
    print(result)
